// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to Config fields that are at their zero value. */
export function configDefaults(m: Config): void {
  if (m.accessTokenLifetimeSeconds === 0n) {
    m.accessTokenLifetimeSeconds = DEFAULT_ACCESS_TOKEN_LIFETIME_SECONDS;
  }
  if (m.refreshTokenLifetimeSeconds === 0n) {
    m.refreshTokenLifetimeSeconds = DEFAULT_REFRESH_TOKEN_LIFETIME_SECONDS;
  }
  if (m.keyLifetimeSeconds === 0n) {
    m.keyLifetimeSeconds = DEFAULT_KEY_LIFETIME_SECONDS;
  }
  if (m.nonceExpireSeconds === 0n) {
    m.nonceExpireSeconds = DEFAULT_NONCE_EXPIRE_SECONDS;
  }
  if (m.jwkRefetchIntervalSeconds === 0n) {
    m.jwkRefetchIntervalSeconds = DEFAULT_JWK_REFETCH_INTERVAL_SECONDS;
  }
  if (m.oauth) {
    oAuthConfigDefaults(m.oauth);
  }
}

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to OAuthConfig fields that are at their zero value. */
export function oAuthConfigDefaults(m: OAuthConfig): void {
  if (m.audience === "") {
    m.audience = DEFAULT_AUDIENCE;
  }
}

// ============================================================
// Merge: Config
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeConfig(dst: Config, src: Config): void {
  if (!dst.oauth && src.oauth) {
    dst.oauth = src.oauth;
  } else if (dst.oauth && src.oauth) {
    mergeOAuthConfig(dst.oauth, src.oauth);
  }
  if (dst.accessTokenLifetimeSeconds === 0n) {
    dst.accessTokenLifetimeSeconds = src.accessTokenLifetimeSeconds;
  }
  if (dst.refreshTokenLifetimeSeconds === 0n) {
    dst.refreshTokenLifetimeSeconds = src.refreshTokenLifetimeSeconds;
  }
  if (dst.keyLifetimeSeconds === 0n) {
    dst.keyLifetimeSeconds = src.keyLifetimeSeconds;
  }
  if (dst.nonceExpireSeconds === 0n) {
    dst.nonceExpireSeconds = src.nonceExpireSeconds;
  }
  if (dst.issuer === "") {
    dst.issuer = src.issuer;
  }
  if (dst.jwkRefetchIntervalSeconds === 0n) {
    dst.jwkRefetchIntervalSeconds = src.jwkRefetchIntervalSeconds;
  }
  if (dst.claimMappingPolicy === "") {
    dst.claimMappingPolicy = src.claimMappingPolicy;
  }
  if (dst.entitlementsPolicy === "") {
    dst.entitlementsPolicy = src.entitlementsPolicy;
  }
  if (dst.entitlementMappings.length === 0) {
    dst.entitlementMappings = src.entitlementMappings;
  }
  if (dst.serviceEntitlements.length === 0) {
    dst.serviceEntitlements = src.serviceEntitlements;
  }
}
// ============================================================
// Merge: OAuthConfig
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeOAuthConfig(dst: OAuthConfig, src: OAuthConfig): void {
  if (dst.enable === false) {
    dst.enable = src.enable;
  }
  if (dst.scopes.length === 0) {
    dst.scopes = src.scopes;
  }
  if (dst.providers.length === 0) {
    dst.providers = src.providers;
  }
  if (dst.audience === "") {
    dst.audience = src.audience;
  }
}
// ============================================================
// Merge: ProviderConfig
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeProviderConfig(
  dst: ProviderConfig,
  src: ProviderConfig,
): void {
  if (dst.enable === false) {
    dst.enable = src.enable;
  }
  if (dst.name === "") {
    dst.name = src.name;
  }
  if (dst.domains.length === 0) {
    dst.domains = src.domains;
  }
  if (dst.issuer === "") {
    dst.issuer = src.issuer;
  }
  if (dst.clientId === "") {
    dst.clientId = src.clientId;
  }
  if (dst.clientSecret === "") {
    dst.clientSecret = src.clientSecret;
  }
  if (dst.authorizationEndpoint === "") {
    dst.authorizationEndpoint = src.authorizationEndpoint;
  }
  if (dst.tokenEndpoint === "") {
    dst.tokenEndpoint = src.tokenEndpoint;
  }
  if (dst.endSessionEndpoint === "") {
    dst.endSessionEndpoint = src.endSessionEndpoint;
  }
  if (dst.scopes.length === 0) {
    dst.scopes = src.scopes;
  }
  if (dst.audience === "") {
    dst.audience = src.audience;
  }
}
