// Merge: QueryValue
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeQueryValue(dst: QueryValue, src: QueryValue): void {
  if (dst.value.case === undefined && src.value.case !== undefined) {
    dst.value = src.value;
  }
}
// ============================================================
// Merge: Predicate
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergePredicate(dst: Predicate, src: Predicate): void {
  if (dst.fieldName === "") {
    dst.fieldName = src.fieldName;
  }
  if (dst.op === 0) {
    dst.op = src.op;
  }
  if (!dst.value && src.value) {
    dst.value = src.value;
  } else if (dst.value && src.value) {
    mergeQueryValue(dst.value, src.value);
  }
  if (dst.values.length === 0) {
    dst.values = src.values;
  }
}
